    public boolean checkDiscountLine(RetailGroupMemberLine _retailGroupMemberLine)
    {
        boolean ret = true;

        try
        {
            // TODO: Create bug 614108 for retail team to bypass this validation.
            // RetailPeriodicDiscountLine must link the RetailGroupMemberLine for Retail, but there is no RetailGroupMemberLine info in GUP.
            ret = next checkDiscountLine(_retailGroupMemberLine);
        }
        catch
        {
            ret = false;
        }

        if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()) &&
            this is GUPMarginComponentPriceAdjustmentLine)
        {
            if (ret == false)
            {
                infolog.clear(infolog.line() - 1);
            }

            return true;
        }
        else
        {
            // TODO: This is used to pass Retail unit tests. Will remove after bug 614108 is fixed.
            if (ret == false)
            {
                if (_retailGroupMemberLine.RecId &&
                    (_retailGroupMemberLine.Product == 0 && _retailGroupMemberLine.Category == 0 && _retailGroupMemberLine.Variant == 0))
                {
                    throw error("@RetailPricing:DoNotSaveEmptyProductLineInDiscount");
                }
                else
                {
                    return checkFailed(strFmt("@RET5769", tableId2name(this.TableId)));
                }
            }
            
            return true;
        }
    }
